style.css:
@-moz-document domain("character.ai") {
html, body {
        background-color: #1c1b1a !important;
        color: #f0f0f0 !important;
    }

    header, .topbar, .top-nav, .top, [class*="Header"] {
        background-color: #1c1b1a !important;
        color: #f0f0f0 !important;
    }

    aside, .sidebar, .drawer, [class*="Side"] {
        background-color: #1f1f1e !important;
        color: #f0f0f0 !important;
    }

    .message-box, textarea, input[type="text"], .input-container, .chat-input, .input-area,
    [class*="input"], [class*="TextArea"] {
        background-color: #3d3b3a !important;
        color: #ffffff !important;
        border: 1px solid #555 !important;
    }

    ::placeholder {
        color: #ccc !important;
    }

    .message, .chat-message, .chat-bubble, [class*="bubble"], [class*="message"] {
        background-color: #1c1b1a !important;
        color: #f0f0f0 !important;
    }

    .bg-white, .bg-gray-100, .bg-gray-200, .bg-gray-50,
    .text-black, .text-gray-800, .text-gray-900 {
        background-color: #1c1b1a !important;
        color: #f0f0f0 !important;
    }

    .border-gray-200, .border-gray-300 {
        border-color: #444 !important;
    }

    button, [role="button"] {
        background-color: #4a4847 !important;
        color: #fff !important;
        border: 1px solid #666 !important;
    }

    button:hover, [role="button"]:hover {
        background-color: #5a5857 !important;
    }
}
